<div class="content-wrapper" style="min-height: 916px;">    <!-- Content Header (Page header) -->    <section class="content-header">        <h1>Xuất excel</h1>        <ol class="breadcrumb">            <li><a href="/<?php echo ADMIN_URL; ?>"><i class="fa fa-dashboard"></i> Home</a></li>            <li class="active">Xuất excel</li>        </ol>               <form method="post">            <select class="form-control" name="status" style="width: 15%;float: left;margin-right: 10px;">                <option value="shipping">ĐH chưa nhận tiền</option>                <option <?php echo $status == 'has_invoiced' ? 'selected' : ''; ?> value="has_invoiced">danh sách gởi</option>            </select>            <select name="shipping_type" class="form-control" style="width: 15%;float: left;margin-right: 10px;">                <option value="f_shipping">Giao hàng nhanh</option>                <option <?php echo $shipping_type == 'post_office' ? 'selected' : ''; ?> value="post_office">Bưu điện</option>            </select>            <input type="text" id="phone"  class="form-control"  value="<?php echo @$_POST['date']; ?>" name="date" style="width: 15%;float: left;margin-right: 10px;" placeholder="Chọn thời gian"/>               <input type="submit" id="report" class="button btn btn-block btn-primary" value="Thống kê" style="float: left;width: 100px;margin-right: 10px;"/>            <input type="submit" name="submit" class="button btn btn-block btn-success" value="Xuất excel" style="width: 100px;"/>            <div style="clear: both"></div>        </form>    </section>        <!-- Main content -->    <section class="content">        <div class="row">            <div class="col-xs-12">                <div class="box" id="list_ajax">                </div>            </div><!-- /.box -->        </div><!-- /.col -->    </section></div><!-- /.row --><script>    var myDate = new Date();    var prettyDate = (myDate.getDate() > 9 ? '' : '0') + myDate.getDate() + '-' + ((myDate.getMonth() + 1) > 9 ? '' : '0') + (myDate.getMonth() + 1) + '-' +            myDate.getFullYear();    $("#phone").datepicker({dateFormat: 'dd-mm-yy'});    if ($("#phone").val() == '') {        $("#phone").val(prettyDate);    }    load_list();    $("#report").click(function () {        load_list();        return false;    });    $("select[name='shipping_type']").change(function () {        load_list();    });    $("select[name='status']").change(function () {        load_list();    });    function load_list() {        var date = $('input[name="date"]').val();        var shipping_type = $('select[name="shipping_type"]').val();        var status = $('select[name="status"]').val();        $.post('<?php echo base_url() . ADMIN_URL; ?>update_shipping/get_export_excel', {date: date, shipping_type: shipping_type, status: status}, function (result) {            $('#list_ajax').html(result);        });    }</script>